 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d',{alpha:false});this.bg=document.createElement('canvas');this.bg.width=WIDTH;this.bg.height=HEIGHT;this.map=-1;this.fx=[];this.poses=new Map();this.animationClock=0;this.portraits={};for(const h of HEROES){const img=new Image();img.src=portraitUrl(h.id);this.portraits[h.id]=img}this.reduced=false;this.detail=true;this.cursor=null;this.shake=0;this.last=0;this.zoomFactor=1;this.camera={x:WIDTH/2,y:HEIGHT/2};this.resize();this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(canvas)}
