 clampCamera(){const hw=this.vw/this.zoom/2,hh=this.vh/this.zoom/2;this.camera.x=hw>=WIDTH/2?WIDTH/2:Math.max(hw,Math.min(WIDTH-hw,this.camera.x));this.camera.y=hh>=HEIGHT/2?HEIGHT/2:Math.max(hh,Math.min(HEIGHT-hh,this.camera.y))}
