 setZoom(factor,point=null){const before=point?this.worldPoint(point.x,point.y):null;this.zoomFactor=Math.max(1,Math.min(3.6,factor));this.zoom=this.fit*this.zoomFactor;if(before){const after=this.worldPoint(point.x,point.y);this.camera.x+=before.x-after.x;this.camera.y+=before.y-after.y}this.clampCamera()}
 pan(dx,dy){this.camera.x-=dx/this.zoom;this.camera.y-=dy/this.zoom;this.clampCamera()}
