const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const num=n=>Math.floor(n).toLocaleString('en-US');
const SAVE_KEY='infinity-defense-v1';
const freshProfile=()=>({kills:0,wins:0,fullTeam:false,tier4:false,perfect:false,highWave:0,records:{},unlocked:[]});
let game=new Game(),profile=freshProfile(),settings={sound:true,volume:.25,motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,detail:true},selected=null,placing=null,paused=false,speed=1,modal=null,lastFocus=null,missionChoice=0,missionDifficulty='heroic',missionMode='campaign',abilitySignature='',lastKills=0,tutorialDismissed=false,saveFailed=false,panelMode='roster';
function safeProfile(p){const out=freshProfile();if(!p||typeof p!=='object')return out;for(const k of ['kills','wins','highWave'])if(Number.isFinite(p[k])&&p[k]>=0&&p[k]<1e10)out[k]=Math.floor(p[k]);for(const k of ['fullTeam','tier4','perfect'])out[k]=p[k]===true;out.unlocked=Array.isArray(p.unlocked)?p.unlocked.filter(x=>ACHIEVEMENTS.some(a=>a.id===x)):[];if(p.records&&typeof p.records==='object')for(const m of MAPS)for(const key of [m.id,...Object.keys(DIFFICULTIES).map(d=>m.id+':'+d)]){const r=p.records[key];if(r&&Number.isFinite(r.stars)&&r.stars>=1&&r.stars<=3&&Number.isFinite(r.wave)&&r.wave>=0)out.records[key]={stars:Math.floor(r.stars),wave:Math.floor(r.wave)}}return out}
function migrateSave(s){if(s.version===1){const old=JSON.parse(s.game);if(old.version!==1)return s;old.version=VERSION;for(const t of old.state.towers){t.x*=2;t.y*=2}for(const e of old.state.enemies){e.x*=2;e.y*=2;e.d*=2}old.state.difficultyScale=1+old.state.map*.08;s.game=JSON.stringify(old);s.version=VERSION}return s}
function readSave(raw){try{const s=migrateSave(JSON.parse(raw));if(s.version!==VERSION)return false;const restored=Game.restore(s.game);if(!restored)return false;game=restored;profile=safeProfile(s.profile);if(s.settings){for(const k of ['sound','motion','detail'])if(typeof s.settings[k]==='boolean')settings[k]=s.settings[k];if(Number.isFinite(s.settings.volume))settings.volume=Math.max(0,Math.min(.7,s.settings.volume))}tutorialDismissed=s.tutorialDismissed===true;lastKills=game.kills;return true}catch{return false}}
let restored=false;try{const raw=localStorage.getItem(SAVE_KEY);if(raw)restored=readSave(raw)}catch{saveFailed=true}if(restored&&game.wave>0)paused=true;
const canvas=$('#battle'),renderer=new Renderer(canvas);renderer.reduced=!settings.motion;renderer.detail=settings.detail;
const audioSystem={ctx:null,lastShot:0,unlock(){if(!this.ctx){try{this.ctx=new(window.AudioContext||window.webkitAudioContext)()}catch{}}if(this.ctx?.state==='suspended')this.ctx.resume().catch(()=>{})},tone(freq,duration=.1,type='sine',volume=.04,slide=0){if(!settings.sound||!this.ctx||this.ctx.state!=='running')return;const o=this.ctx.createOscillator(),g=this.ctx.createGain(),now=this.ctx.currentTime;o.type=type;o.frequency.setValueAtTime(freq,now);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(20,freq+slide),now+duration);g.gain.setValueAtTime(volume*settings.volume,now);g.gain.exponentialRampToValueAtTime(.001,now+duration);o.connect(g);g.connect(this.ctx.destination);o.start();o.stop(now+duration)},play(type){if(type==='attack'){const n=performance.now();if(n-this.lastShot<90)return;this.lastShot=n;this.tone(380,.08,'triangle',.04,-240)}else if(type==='place'){this.tone(390,.1,'sine',.12);setTimeout(()=>this.tone(650,.15,'sine',.12),70)}else if(type==='upgrade'||type==='clear'){[440,554,660].forEach((n,i)=>setTimeout(()=>this.tone(n,.22,'sine',.15),i*80))}else if(type==='ability'){this.tone(140,.65,'sawtooth',.09,800)}else if(type==='leak'){this.tone(160,.2,'triangle',.13,-70)}else if(type==='boss'||type==='defeat'){this.tone(90,.7,'sawtooth',.12,-30)}}};
document.addEventListener('pointerdown',()=>audioSystem.unlock(),{once:true});document.addEventListener('keydown',()=>audioSystem.unlock(),{once:true});
function toast(message,bad=false){const el=document.createElement('div');el.className='toast'+(bad?' bad':'');el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),4200);while($('#toast-region').children.length>3)$('#toast-region').firstChild.remove()}
function serializeSave(){return JSON.stringify({version:VERSION,game:game.serialize(),profile,settings,tutorialDismissed})}
function save(){try{localStorage.setItem(SAVE_KEY,serializeSave());saveFailed=false;$('#save-status').textContent='Progress saved on this device'}catch{if(!saveFailed)toast('Device storage is unavailable. Export your save in Settings.',true);saveFailed=true;$('#save-status').textContent='Storage unavailable · export your save'}}
function updateProfile(){if(game.mode!=='sandbox'){profile.kills+=Math.max(0,game.kills-lastKills);profile.highWave=Math.max(profile.highWave,game.wave);profile.fullTeam||=new Set(game.towers.map(t=>t.hero)).size===8;profile.tier4||=game.towers.some(t=>t.upgrades.includes(4));for(const a of ACHIEVEMENTS)if(!profile.unlocked.includes(a.id)&&a.check(profile)){profile.unlocked.push(a.id);toast('Achievement unlocked · '+a.name);audioSystem.play('upgrade')}}lastKills=game.kills;$('#achievement-count').textContent=profile.unlocked.length+'/8'}
function chooseHero(id){if(!['build','wave'].includes(game.status))return;if(!HEROES.some(h=>h.id===id))return;panelMode='roster';selected=null;placing=placing===id?null:id;renderer.cursor=renderer.cursor||{x:renderer.camera.x,y:renderer.camera.y};if(placing){tutorialDismissed=true;$('#onboarding').classList.add('hidden')}renderPanel();updateHUD();}
function renderPanel(){$('#hero-footer').replaceChildren();const t=game.towers.find(t=>t.id===selected);$('#roster-tab').classList.toggle('active',panelMode==='roster');$('#squad-tab').classList.toggle('active',panelMode==='squad');if(!t&&panelMode==='squad'){renderSquad();return}if(!t){selected=null;$('#panel-title').textContent='Choose your hero';$('#roster-count').textContent=String(HEROES.length).padStart(2,'0');const hero=HEROES.find(h=>h.id===placing);$('#panel-content').innerHTML=(hero?`<div class="deploy-note"><button data-action="cancel-place">Cancel</button><strong>Deploy ${hero.name}</strong><br>${hero.role}. Select clear ground.<br>Cost: ◈ ${num(hero.cost)}</div>`:'')+`<div class="hero-grid">${HEROES.map((h,i)=>`<button class="hero-card ${placing===h.id?'chosen':''} ${game.cash<h.cost?'unaffordable':''}" data-hero="${h.id}" aria-label="Deploy ${h.name}, ${h.cost} credits" aria-pressed="${placing===h.id}" title="${h.role} · ${h.cost} credits"><div class="hero-art" style="--hero-color:${h.color}"><span class="hero-key">${i+1}</span><img src="${portraitUrl(h.id)}" alt="${h.name}" draggable="false"></div><div class="hero-info"><strong>${h.name}</strong><span><span>${h.role.split(' / ')[0]}</span><b>◈ ${h.cost}</b></span></div></button>`).join('')}</div>`;return}
 const h=HEROES.find(h=>h.id===t.hero),s=towerStats(t);$('#panel-title').textContent='Hero upgrades';$('#roster-count').textContent=t.upgrades.join('–');$('#panel-content').innerHTML=`<button class="back-button" data-action="all-heroes">← All heroes</button><div class="selected-hero"><img src="${portraitUrl(h.id)}" alt="${h.name}"><div><p>${h.alias}</p><h3>${h.name}</h3><small>${h.role}</small></div></div><div class="stat-grid"><div><small>DAMAGE</small><strong>${Math.round(s.damage)}</strong></div><div><small>RANGE</small><strong>${s.range}</strong></div><div><small>ATK / SEC</small><strong>${(1/s.rate).toFixed(1)}</strong></div></div><div class="target-row"><span>Target priority</span><select id="target-select" aria-label="Target priority">${['first','strong','close','last'].map(p=>`<option value="${p}" ${t.target===p?'selected':''}>${{first:'First',strong:'Strongest',close:'Closest',last:'Last'}[p]}</option>`).join('')}</select></div><div class="branches">${h.branches.map((branch,b)=>{const state=upgradeState(t,b,game.cash),u=state.upgrade;return `<div class="branch"><h4>${branch.name}</h4><div class="tier-pips">${[1,2,3,4].map(n=>`<i class="${t.upgrades[b]>=n?'filled':''}"></i>`).join('')}</div><div class="upgrade-card"><span class="tier-label">${u?'TIER '+(t.upgrades[b]+1):'SPECIALIZATION'}</span><strong>${u?u.name:state.reason}</strong><p>${u?u.description:t.upgrades[b]===4?'Your hero has mastered this path.':'You can reach tier 2 on this branch.'}</p><button data-upgrade="${b}" ${state.allowed?'':'disabled'}>${u?'Upgrade · ◈ '+num(u.cost):t.upgrades[b]===4?'MAXED':'LOCKED'}</button></div><div class="branch-path">${branch.upgrades.map((u,j)=>`<span class="${j<t.upgrades[b]?'bought':''}">${j<t.upgrades[b]?'✓':'◇'} ${u.name}</span>`).join('')}</div></div>`}).join('')}</div><div class="hero-special">${Math.max(...t.upgrades)>=3?`✦ ${h.ability.name}: ${h.ability.description}`:'✦ Reach tier 3 on either branch to unlock '+h.ability.name+'.'}${s.detect?'<br>◉ Cloak detection active':''}${s.income?'<br>◈ Generates '+s.income+' credits per wave':''}</div><div class="sell-row"><small><span id="tower-kills">${num(t.kills)}</span> eliminations<br><span id="tower-damage">${num(t.damage)}</span> damage dealt</small><button data-action="sell">Sell · ◈ ${num(Math.floor(t.spent*7/10))}</button></div>`;$('#hero-footer').append($('#panel-content .sell-row'));
}
function updateHUD(){const m=MAPS[game.map],d=DIFFICULTIES[game.difficulty];$('#squad-count').textContent=game.towers.length;$('#sector-kills').textContent=num(game.kills);$('#zoom-reset').textContent=Math.round(renderer.zoomFactor*100)+'%';$('#region').textContent=m.region;$('#map-name').textContent=m.name;$('#map-subtitle').textContent=m.subtitle;$('#cash').textContent=num(game.cash);$('#lives').innerHTML=`${game.lives} <em>/ ${game.maxLives}</em>`;$('#wave').innerHTML=`${String(game.wave).padStart(2,'0')} <em>/ ${game.mode==='campaign'?m.waves:'∞'}</em>`;$('#difficulty-label').textContent=d.name.toUpperCase()+(game.mode==='sandbox'?' · SANDBOX':'');$('#phase-label').textContent=paused?'TACTICAL PAUSE':game.status==='wave'?'INVASION IN PROGRESS':game.status==='build'?'PREPARATION PHASE':game.status.toUpperCase();$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'Resume game':'Pause game');$('#speed').textContent=speed+'×';$('#auto').setAttribute('aria-pressed',String(game.auto));
 const next=wavePlan(game.wave+1,game.map);const types=[...new Set(next.map(p=>p.type))];if(game.status==='wave'){$('#wave-title').textContent='Wave '+game.wave+' · Hold the line';$('#wave-detail').textContent=`${game.enemies.length} on the field · ${game.plan.length} incoming`;}else{$('#wave-title').textContent=game.wave?`Round ${game.wave} complete!`:'Ready to defend?';$('#wave-detail').textContent=`Next: ${next.length} enemies${types.includes('cloak')?' · Cloaked enemies':''}${types.includes('armor')?' · Armored units':''}${(game.wave+1)%10===0?' · BOSS INCOMING':''}`;}
 const start=$('#start');start.disabled=game.status!=='build';start.innerHTML=game.status==='wave'?'Defending… <span>◆</span>':`Play round ${game.wave+1} <span>▶</span>`;
 $('#onboarding').classList.toggle('hidden',tutorialDismissed||game.wave>0||game.towers.length>0);$('#placement-hint').classList.toggle('hidden',!placing);if(placing)$('#placement-hint').textContent=`Deploy ${HEROES.find(h=>h.id===placing).name} · click clear ground · Esc to cancel`;
 for(const b of $$('[data-hero]'))b.classList.toggle('unaffordable',game.cash<HEROES.find(h=>h.id===b.dataset.hero).cost);
 const t=game.towers.find(t=>t.id===selected);if(t){for(const b of $$('[data-upgrade]'))b.disabled=!upgradeState(t,Number(b.dataset.upgrade),game.cash).allowed;const k=$('#tower-kills'),damage=$('#tower-damage');if(k)k.textContent=num(t.kills);if(damage)damage.textContent=num(t.damage)}
 const available=game.towers.filter(t=>Math.max(...t.upgrades)>=3),signature=available.map(t=>t.id).join(',');if(signature!==abilitySignature){abilitySignature=signature;$('#ability-slots').innerHTML=available.length?available.map(t=>{const h=HEROES.find(h=>h.id===t.hero);return `<button class="power-button" data-ability="${t.id}" aria-label="Activate ${h.ability.name}" title="${h.ability.name}: ${h.ability.description}"><img src="${portraitUrl(h.id)}" alt=""><strong>${h.ability.name}</strong><span class="cooldown hidden"></span></button>`}).join(''):'<span class="powers-empty">Upgrade a hero to unlock their signature power.</span>'}
 for(const b of $$('[data-ability]')){const t=game.towers.find(t=>t.id===Number(b.dataset.ability));b.disabled=t.ability>0||t.disabled>0||game.status!=='wave'||paused;const cd=b.querySelector('.cooldown');cd.classList.toggle('hidden',t.ability<=0);cd.textContent=Math.ceil(t.ability)+'s'}
 const boss=game.enemies.find(e=>ENEMIES[e.type].boss);$('#boss-bar').classList.toggle('hidden',!boss);if(boss)$('#boss-bar').innerHTML=`<strong>${ENEMIES[boss.type].name.toUpperCase()}</strong><div class="track"><div class="fill" style="width:${boss.hp/boss.maxHp*100}%"></div></div><small>${num(boss.hp)} / ${num(boss.maxHp)}</small>`;
}
function renderSquad(){$('#panel-title').textContent='Your deployed team';$('#roster-count').textContent=String(game.towers.length).padStart(2,'0');$('#panel-content').innerHTML=game.towers.length?`<div class="squad-list">${game.towers.map(t=>{const h=HEROES.find(h=>h.id===t.hero);return `<button class="squad-card" data-select-tower="${t.id}"><img src="${portraitUrl(h.id)}" alt=""><div><strong>${h.name}</strong><small>${t.upgrades.join(' / ')} · ${Math.max(...t.upgrades)>=3?'Ability unlocked':'Developing hero'}</small><em>${num(t.kills)} eliminations · ${num(t.damage)} damage</em></div></button>`}).join('')}</div>`:'<div class="empty-squad">Your team is waiting for orders.<br>Recruit heroes to deploy your first defenders.</div>'}
function showForecast(){showModal('Incoming wave intelligence',`<p class="modal-intro">Plan your next five waves. Armored units need piercing damage; Dark Elves require cloak detection. Bosses arrive every tenth wave.</p>${[1,2,3,4,5].map(i=>{const wave=game.wave+i,plan=wavePlan(wave,game.map),counts={};for(const e of plan)counts[e.type]=(counts[e.type]||0)+1;return `<article class="forecast-wave"><h3>Wave ${wave} <span>${plan.length} enemies · ${wave%10===0?'BOSS ENCOUNTER':'INVASION'}</span></h3><div class="enemy-chips">${Object.entries(counts).map(([key,count])=>`<span class="enemy-chip"><i style="background:${ENEMIES[key].color}"></i>${ENEMIES[key].name}<b>× ${count}</b></span>`).join('')}</div></article>`}).join('')}`)}
function showModal(name,content,{narrow=false,close=true}={}){if(!modal)lastFocus=document.activeElement;modal=name;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${narrow?'narrow':''}" role="dialog" aria-modal="true" aria-label="${name}">${close?`<div class="modal-head"><div><span class="eyebrow">S.H.I.E.L.D. COMMAND</span><h2>${name}</h2></div><button data-action="close-modal" aria-label="Close dialog">×</button></div>`:''}${content}</section></div>`;requestAnimationFrame(()=>$('#modal-root button, #modal-root select')?.focus())}
function closeModal(){modal=null;$('#modal-root').innerHTML='';lastFocus?.focus();if(game.status==='victory'||game.status==='defeat')showResult();}
function missionModal(){missionChoice=game.map;missionDifficulty=game.difficulty;missionMode=game.mode;drawMissions()}
function drawMissions(){showModal('Choose your battleground',`<div class="map-grid">${MAPS.map((m,i)=>{const r=profile.records[m.id];return `<button class="map-card ${i===missionChoice?'active':''}" data-map="${i}"><canvas class="map-preview" width="330" height="180" data-preview="${i}" aria-hidden="true"></canvas><div class="map-card-copy"><h3>${m.name}</h3><p>${m.subtitle}</p><small>${r?'★'.repeat(r.stars)+' · MISSION COMPLETE':m.waves+' WAVES · '+(m.paths.length>1?'SPLIT ROUTE':'SINGLE ROUTE')}</small></div></button>`}).join('')}</div><p class="mission-brief">${MAPS[missionChoice].brief}</p><div class="mission-options"><label>DIFFICULTY<select id="mission-difficulty">${Object.entries(DIFFICULTIES).map(([k,d])=>`<option value="${k}" ${k===missionDifficulty?'selected':''}>${d.name} · ${d.lives} integrity</option>`).join('')}</select></label><label>GAME MODE<select id="mission-mode">${['campaign','endless','sandbox'].map(k=>`<option value="${k}" ${k===missionMode?'selected':''}>${{campaign:'Campaign',endless:'Endless survival',sandbox:'Sandbox · unlimited credits'}[k]}</option>`).join('')}</select></label><button class="primary-button" data-action="launch-mission">Deploy to ${MAPS[missionChoice].name} <span>→</span></button></div><p class="fine-print">All battlegrounds and heroes are available. A new mission replaces your current in-progress mission; medals and achievements are kept.</p>`);const prior=renderer.map;for(const c of $$('[data-preview]')){renderer.createBackground(Number(c.dataset.preview));c.getContext('2d').drawImage(renderer.bg,0,0,330,180)}renderer.createBackground(prior<0?game.map:prior)}
function newMission(){game=new Game({map:missionChoice,difficulty:missionDifficulty,mode:missionMode,seed:Date.now()>>>0});selected=null;placing=null;paused=false;lastKills=0;speed=1;abilitySignature='reset';panelMode='roster';modal=null;renderer.fx=[];renderer.poses.clear();renderer.resetCamera();$('#modal-root').innerHTML='';renderPanel();updateHUD();save();canvas.focus();toast(MAPS[game.map].name+' · Your defense begins.');}
function showGuide(tab='heroes'){const tabs=`<div class="tabs">${['heroes','enemies','how to play'].map(k=>`<button data-guide="${k}" class="${tab===k?'active':''}">${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div>`;let content='';if(tab==='heroes')content=`<div class="guide-grid">${HEROES.map(h=>`<button class="guide-item" data-hero-guide="${h.id}" style="text-align:left"><img src="${portraitUrl(h.id)}" alt="${h.name}"><div><h3>${h.name}</h3><p>${h.role}<br>${h.damage} damage · ${h.range} range · ◈ ${h.cost}</p><small>${h.branches.map(b=>b.name).join(' / ')} →</small></div></button>`).join('')}</div>`;else if(tab==='enemies')content=`<div class="guide-grid">${Object.values(ENEMIES).map(e=>`<article class="guide-item"><span class="enemy-icon" style="color:${e.color}">${e.boss?'♜':e.cloak?'◌':e.armor?'⬡':'◇'}</span><div><h3>${e.name}</h3><p>${e.description}</p><small>${num(e.hp)} base HP · ${e.speed} speed · ${e.leak} integrity damage</small></div></article>`).join('')}</div>`;else content=`<div class="how-grid"><article><h3>01 · Build your defense</h3><p>Drag a hero from the shop onto clear ground, or select a hero card and click beside the road. Buildings and roads cannot be built on. The circle shows attack range. Credits come from defeating enemies and finishing waves. You can deploy and upgrade during combat.</p></article><article><h3>02 · Choose your specialization</h3><p>Every hero has two branches with four tiers each. Once one branch reaches tier 3, the other is capped at tier 2. A 4–2 or 2–4 build is the maximum. Multiple copies of a hero can use different specializations.</p></article><article><h3>03 · Know your enemy</h3><p>Armored units resist ordinary attacks; Doctor Strange and Black Panther pierce armor from the start. Dark Elves first arrive on wave 7 and need detection. Splash can hit cloaked enemies indirectly. Bosses resist slows, stuns, and knockback.</p></article><article><h3>04 · Use your powers</h3><p>Tier 3 unlocks a hero’s active ability in the bar below the map. Each deployed hero has a separate cooldown. Captain America’s leadership aura does not stack with another Captain; the strongest aura applies. Wakandan science pays after each wave.</p></article><article><h3>05 · Complete the mission</h3><p>Hold all waves to win. Loki arrives on wave 10, Ultron on 20, and Thanos on 30. Earn three stars for perfect integrity, two for keeping at least half, and one for survival. The Compound has 40 waves. Continue any victory into endless mode.</p></article><article><h3>06 · Tactical controls</h3><p>Keys 1–8 select heroes. Arrow keys move the deployment cursor; Enter deploys. Space pauses. N starts a wave. F changes speed. Escape cancels placement. Auto starts the next wave after a 3-second preparation period. Tab navigates all menus and hero cards.</p></article><article><h3>07 · Saves & sandbox</h3><p>Your mission autosaves on this browser. Export a backup in Settings to move devices. Import replaces your current save after validation. Sandbox starts with unlimited credits, prevents defeat, and enables jumping to any wave from Settings. Sandbox progress does not unlock achievements.</p></article><article><h3>08 · Plan for later waves</h3><p>Enemy health grows each wave and maps get progressively harder. Set a boss killer to Strongest, use webs near damage towers, and place leadership heroes centrally. Sell heroes for 70% of the total investment. Abilities recharge only while a wave is active.</p></article></div>`;showModal('Field guide',tabs+content)}
function heroGuide(id){const h=HEROES.find(h=>h.id===id);showModal(h.name,`<button class="back-button" data-guide="heroes">← Hero roster</button><p class="modal-intro">${h.role}. Ability: <strong>${h.ability.name}</strong> — ${h.ability.description} ${h.ability.cooldown}s cooldown. Unlock at tier 3.</p><div class="how-grid">${h.branches.map(b=>`<article><h3>${b.name}</h3>${b.upgrades.map((u,i)=>`<p style="margin-bottom:14px"><strong style="color:#e0d0ef">${i+1}. ${u.name} · ◈ ${num(u.cost)}</strong><br>${u.description}</p>`).join('')}</article>`).join('')}</div>`)}
function showAchievements(){showModal('Hall of heroes',`<p class="modal-intro">${profile.unlocked.length} of ${ACHIEVEMENTS.length} achievements unlocked · ${num(profile.kills)} invaders defeated · ${profile.wins} mission victories</p><div class="achievement-grid">${ACHIEVEMENTS.map(a=>`<article class="achievement ${profile.unlocked.includes(a.id)?'unlocked':''}"><span>${profile.unlocked.includes(a.id)?'✦':'◇'}</span><div><h3>${a.name}</h3><p>${a.text}</p></div></article>`).join('')}</div>`)}
function showSettings(){showModal('Settings',`<div class="setting-row"><label for="sound-setting">Combat audio<small>Synthesized effects for attacks, upgrades, and powers.</small></label><input type="checkbox" id="sound-setting" ${settings.sound?'checked':''}></div><div class="setting-row"><label for="volume-setting">Volume</label><input type="range" id="volume-setting" min="0" max="0.7" step="0.01" value="${settings.volume}"></div><div class="setting-row"><label for="motion-setting">Animated effects<small>Turn off for reduced motion and screen shake.</small></label><input type="checkbox" id="motion-setting" ${settings.motion?'checked':''}></div><div class="setting-row"><label for="detail-setting">High-detail effects<small>Turn off to reduce combat particles and glow.</small></label><input type="checkbox" id="detail-setting" ${settings.detail?'checked':''}></div>${game.mode==='sandbox'?`<div class="setting-row"><label for="sandbox-wave">Sandbox wave<small>Clear current enemies and prepare this wave.</small></label><input id="sandbox-wave" type="number" min="1" max="200" value="${game.wave+1}" style="width:70px"><button class="secondary-button" data-action="sandbox-wave">Set</button></div>`:''}<div class="settings-actions"><button class="secondary-button" data-action="export">Export save</button><button class="secondary-button" data-action="import">Import save</button><button class="secondary-button danger-button" data-action="restart">Restart mission</button></div><p class="fine-print">Infinity Defense · v3.0 · Unofficial Marvel fan game. Characters belong to Marvel. No affiliation or endorsement. Device-local progress; no account required.</p>`,{narrow:true})}
function recordVictory(){const stars=game.leaks===0?3:game.lives>=game.maxLives*.5?2:1;profile.wins++;profile.perfect||=game.leaks===0;const key=MAPS[game.map].id;for(const k of[key,key+':'+game.difficulty]){const old=profile.records[k];profile.records[k]={stars:Math.max(old?.stars||0,stars),wave:Math.max(old?.wave||0,game.wave)}}updateProfile();save()}
function showResult(){const win=game.status==='victory';showModal(win?'Mission complete':'Defense breached',`<div class="result"><span class="eyebrow">${MAPS[game.map].name.toUpperCase()} · ${DIFFICULTIES[game.difficulty].name.toUpperCase()}</span><div class="emblem">${win?'✦':'◇'}</div><h2>${win?'Earth still stands.':'We’re not done yet.'}</h2><p>${win?'Your team held the line. Take the fight to the next battleground.':'The invasion broke through. Rebuild your formation and try again.'}</p>${win?`<div class="stars">${'★'.repeat(game.leaks===0?3:game.lives>=game.maxLives*.5?2:1)}${'☆'.repeat(game.leaks===0?0:game.lives>=game.maxLives*.5?1:2)}</div>`:''}<div class="result-stats"><div><strong>${game.wave}</strong><small>WAVES REACHED</small></div><div><strong>${num(game.kills)}</strong><small>ELIMINATIONS</small></div><div><strong>${num(game.totalDamage)}</strong><small>DAMAGE DEALT</small></div></div><div class="result-buttons"><button class="primary-button" data-action="result-missions">${win?'Choose next mission':'Change strategy'} →</button><button class="secondary-button" data-action="${win?'continue-endless':'retry'}">${win?'Continue endless':'Retry mission'}</button></div></div>`,{narrow:true,close:false})}
function confirmRestart(){showModal('Restart this mission?',`<p class="modal-intro">This replaces your current formation and starts ${MAPS[game.map].name} from wave 1. Your medals and achievements will stay.</p><div class="settings-actions"><button class="secondary-button" data-action="close-modal">Keep playing</button><button class="primary-button" data-action="retry">Restart mission</button></div>`,{narrow:true})}
function exportSave(){save();const raw=serializeSave();showModal('Save backup',`<p class="modal-intro">Download your backup, or copy the save text below and keep it in a .json file. Import that file from Settings to restore your mission.</p><textarea id="backup-text" aria-label="Save backup text" readonly style="width:100%;height:180px;padding:12px;background:#392348;color:#f6e9ff;border:2px solid #b56cff;border-radius:9px;resize:vertical"></textarea><div class="settings-actions"><a id="backup-download" class="primary-button" download="infinity-defense-save.json">Download backup</a><button class="secondary-button" data-action="copy-backup">Copy save text</button></div>`,{narrow:true});$('#backup-text').value=raw;$('#backup-download').href='data:application/json;charset=utf-8,'+encodeURIComponent(raw)}
let pendingImport=null;$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>4e6){toast('This save is too large.',true);return}const raw=await f.text();try{const s=JSON.parse(raw);if(s.version!==VERSION||!Game.restore(s.game))throw Error();pendingImport=raw;showModal('Import this save?',`<p class="modal-intro">This will replace the current mission, records, and settings with your imported backup. Export your current save first if you want to keep it.</p><div class="settings-actions"><button class="secondary-button" data-action="export">Export current save</button><button class="primary-button" data-action="confirm-import">Replace with imported save</button></div>`,{narrow:true})}catch{toast('That file is not a valid Infinity Defense save.',true)}});
document.addEventListener('click',async e=>{const el=e.target.closest('button,a.brand');if(!el){e.target.closest('.upgrade-card')?.querySelector('[data-upgrade]')?.click();return;}if(el.dataset.hero){if(performance.now()<suppressShopClickUntil)return;chooseHero(el.dataset.hero);return}if(el.dataset.upgrade!==undefined){if(game.upgrade(selected,Number(el.dataset.upgrade))){renderPanel();updateProfile();updateHUD();save()}return}if(el.dataset.ability){if(game.ability(Number(el.dataset.ability))){updateHUD();save()}return}if(el.dataset.map){missionChoice=Number(el.dataset.map);drawMissions();return}if(el.dataset.guide){showGuide(el.dataset.guide);return}if(el.dataset.heroGuide){heroGuide(el.dataset.heroGuide);return;}
 if(el.dataset.selectTower){selected=Number(el.dataset.selectTower);placing=null;const t=game.towers.find(t=>t.id===selected);if(t)renderer.focusOn(t.x,t.y);renderPanel();return;}
 const action=el.dataset.action||el.id;switch(action){
  case'missions':missionModal();break;case'guide':showGuide('how to play');break;case'achievements':showAchievements();break;case'settings':showSettings();break;
  case'forecast':case'phase-label':showForecast();break;
  case'roster-tab':panelMode='roster';selected=null;placing=null;renderPanel();updateHUD();break;
  case'squad-tab':panelMode='squad';selected=null;placing=null;renderPanel();updateHUD();break;
  case'zoom-in':renderer.setZoom(renderer.zoomFactor*1.25);updateHUD();break;
  case'zoom-out':renderer.setZoom(renderer.zoomFactor/1.25);updateHUD();break;
  case'zoom-reset':renderer.resetCamera();updateHUD();break;
  case'start':if(game.towers.length===0){toast('Deploy at least one hero before starting.',true);return}paused=false;game.startWave();tutorialDismissed=true;updateHUD();save();break;
  case'pause':paused=!paused;updateHUD();save();break;case'speed':speed=speed===1?2:speed===2?3:1;updateHUD();break;case'auto':game.auto=!game.auto;updateHUD();save();break;
  case'dismiss-tip':tutorialDismissed=true;updateHUD();save();break;
  case'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('Full screen is unavailable in this browser.')}break;
  case'cancel-place':case'all-heroes':panelMode='roster';placing=null;selected=null;renderPanel();updateHUD();break;
  case'sell':if(selected){game.sell(selected);selected=null;renderPanel();updateHUD();save()}break;
  case'close-modal':closeModal();break;
  case'launch-mission':if(game.towers.length>0||game.wave>0){showModal('Begin a new mission?',`<p class="modal-intro">Deploy to ${MAPS[missionChoice].name} in ${DIFFICULTIES[missionDifficulty].name} difficulty. This replaces your current mission. Your medals and achievements stay.</p><div class="settings-actions"><button class="secondary-button" data-action="missions">Back to battlegrounds</button><button class="primary-button" data-action="new-mission">Begin mission</button></div>`,{narrow:true})}else newMission();break;
  case'new-mission':newMission();break;case'result-missions':missionModal();break;
  case'continue-endless':game.status='build';game.mode='endless';paused=false;modal=null;$('#modal-root').innerHTML='';updateHUD();save();break;
  case'retry':missionChoice=game.map;missionDifficulty=game.difficulty;missionMode=game.mode;newMission();break;
  case'copy-backup':{const field=$('#backup-text');field.select();if(navigator.clipboard)navigator.clipboard.writeText(field.value).then(()=>toast('Save text copied.')).catch(()=>toast('Save text selected. Use Copy to keep your backup.'));else toast('Save text selected. Use Copy to keep your backup.');break;}case'restart':confirmRestart();break;case'export':exportSave();break;case'import':$('#import-file').click();break;
  case'confirm-import':if(pendingImport&&readSave(pendingImport)){pendingImport=null;selected=null;placing=null;paused=true;abilitySignature='reset';renderer.reduced=!settings.motion;renderer.detail=settings.detail;modal=null;$('#modal-root').innerHTML='';renderPanel();updateHUD();save();toast('Save restored. Resume when you’re ready.');if(['victory','defeat'].includes(game.status))showResult()}break;
  case'sandbox-wave':{const wave=Number($('#sandbox-wave').value);if(game.mode==='sandbox'&&Number.isInteger(wave)&&wave>=1&&wave<=200){game.wave=wave-1;game.enemies=[];game.plan=[];game.status='build';game.lives=game.maxLives;closeModal();updateHUD();save();toast('Wave '+wave+' is ready.')}break;}
 }if(el.matches('a.brand')){e.preventDefault();missionModal()}
});
document.addEventListener('change',e=>{switch(e.target.id){case'target-select':{const t=game.towers.find(t=>t.id===selected);if(t)t.target=e.target.value;save();break}case'mission-difficulty':missionDifficulty=e.target.value;break;case'mission-mode':missionMode=e.target.value;break;case'sound-setting':settings.sound=e.target.checked;save();break;case'volume-setting':settings.volume=Number(e.target.value);save();break;case'motion-setting':settings.motion=e.target.checked;renderer.reduced=!settings.motion;save();break;case'detail-setting':settings.detail=e.target.checked;renderer.detail=settings.detail;save();break}});
function canvasPos(e){return renderer.worldPoint(e.clientX,e.clientY)}
function roundBanner(title,subtitle){if(!settings.motion)return;const banner=$('#round-banner');banner.classList.remove('show');banner.textContent=title;const sub=document.createElement('small');sub.textContent=subtitle;banner.append(sub);void banner.offsetWidth;banner.classList.add('show');setTimeout(()=>banner.classList.remove('show'),2200)}
let panState=null,suppressMapClick=false,pinchDistance=0,suppressShopClickUntil=0,shopDrag=null;const touchPoints=new Map();
document.addEventListener('pointerdown',e=>{const card=e.target.closest('[data-hero]');if(!card||modal||e.button!==0)return;shopDrag={id:card.dataset.hero,x:e.clientX,y:e.clientY,active:false,pointer:e.pointerId};});
document.addEventListener('pointermove',e=>{if(!shopDrag||e.pointerId!==shopDrag.pointer)return;if(!shopDrag.active&&Math.hypot(e.clientX-shopDrag.x,e.clientY-shopDrag.y)>8){shopDrag.active=true;placing=shopDrag.id;selected=null;tutorialDismissed=true;suppressShopClickUntil=performance.now()+1000;$('#onboarding').classList.add('hidden');for(const card of $$('[data-hero]'))card.classList.toggle('chosen',card.dataset.hero===placing)}if(shopDrag.active){e.preventDefault();renderer.cursor=canvasPos(e);updateHUD()}},{passive:false});
document.addEventListener('pointerup',e=>{if(!shopDrag||e.pointerId!==shopDrag.pointer)return;const drag=shopDrag;shopDrag=null;if(!drag.active)return;suppressShopClickUntil=performance.now()+500;suppressMapClick=true;const r=canvas.getBoundingClientRect();if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom)deployAt(canvasPos(e));else{placing=null;renderPanel();updateHUD()}setTimeout(()=>suppressMapClick=false,250)});
document.addEventListener('pointercancel',()=>{if(shopDrag?.active){placing=null;renderPanel();updateHUD()}shopDrag=null});
canvas.addEventListener('wheel',e=>{e.preventDefault();renderer.setZoom(renderer.zoomFactor*Math.exp(-e.deltaY*.0015),{x:e.clientX,y:e.clientY});updateHUD()},{passive:false});
canvas.addEventListener('pointerdown',e=>{touchPoints.set(e.pointerId,{x:e.clientX,y:e.clientY});if(touchPoints.size===2){const [a,b]=[...touchPoints.values()];pinchDistance=Math.hypot(a.x-b.x,a.y-b.y);suppressMapClick=true;return}if(!placing||e.button===1||e.button===2){panState={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId)}});
canvas.addEventListener('pointermove',e=>{if(shopDrag?.active)return;if(touchPoints.has(e.pointerId))touchPoints.set(e.pointerId,{x:e.clientX,y:e.clientY});if(touchPoints.size===2){const[a,b]=[...touchPoints.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(pinchDistance)renderer.setZoom(renderer.zoomFactor*d/pinchDistance,{x:(a.x+b.x)/2,y:(a.y+b.y)/2});pinchDistance=d;suppressMapClick=true;return}if(panState){const dx=e.clientX-panState.x,dy=e.clientY-panState.y;if(Math.hypot(e.clientX-panState.startX,e.clientY-panState.startY)>5)panState.moved=true;if(panState.moved){renderer.pan(dx,dy);suppressMapClick=true}panState.x=e.clientX;panState.y=e.clientY}renderer.cursor=canvasPos(e);canvas.style.cursor=panState?.moved?'grabbing':placing?'crosshair':game.towers.some(t=>distance(t,renderer.cursor)<33)?'pointer':'grab'});
function endPan(e){touchPoints.delete(e.pointerId);if(touchPoints.size<2)pinchDistance=0;if(panState?.moved)suppressMapClick=true;panState=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);setTimeout(()=>suppressMapClick=false,200)}
canvas.addEventListener('pointerup',endPan);canvas.addEventListener('pointercancel',endPan);
$('#minimap').addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect();renderer.camera={x:(e.clientX-r.left)/r.width*WIDTH,y:(e.clientY-r.top)/r.height*HEIGHT};renderer.setZoom(Math.max(1.6,renderer.zoomFactor));updateHUD()});
$('#minimap').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();renderer.resetCamera();updateHUD()}});
canvas.addEventListener('pointerleave',()=>{if(!placing)renderer.cursor=null});
function deployAt(p){const h=HEROES.find(h=>h.id===placing);if(!h)return;if(game.cash<h.cost){toast('Need '+num(h.cost-game.cash)+' more credits for '+h.name+'.',true);return}if(game.towers.length>=40){toast('The deployment limit is 40 heroes.',true);return}const t=game.place(placing,p.x,p.y);if(!t){toast('Choose open ground, away from roads, buildings, and heroes.',true);return}selected=t.id;placing=null;tutorialDismissed=true;renderPanel();updateProfile();updateHUD();save();}
canvas.addEventListener('click',e=>{if(modal||suppressMapClick){suppressMapClick=false;return}const p=canvasPos(e);renderer.cursor=p;if(placing){deployAt(p);return}selected=game.towers.find(t=>distance(t,p)<36)?.id||null;renderPanel();updateHUD()});
canvas.addEventListener('contextmenu',e=>{e.preventDefault();placing=null;selected=null;renderPanel();updateHUD()});
document.addEventListener('keydown',e=>{if(modal){if(e.key==='Escape'){e.preventDefault();if(!['Mission complete','Defense breached'].includes(modal))closeModal()}if(e.key==='Tab'){const focusable=$$('#modal-root button:not(:disabled),#modal-root input,#modal-root select');const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}return}if(e.target.matches('input,select,textarea'))return;if(e.key==='Escape'){placing=null;selected=null;renderPanel();updateHUD();return}if(/^[1-8]$/.test(e.key)){chooseHero(HEROES[Number(e.key)-1].id);canvas.focus();return}if(e.code==='Space'&&!e.target.matches('button')){e.preventDefault();paused=!paused;updateHUD();return}if(e.key.toLowerCase()==='n')$('#start').click();if(e.key.toLowerCase()==='f')$('#speed').click();if(placing&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Enter'].includes(e.key)){e.preventDefault();if(!renderer.cursor)renderer.cursor={x:340,y:270};const p=renderer.cursor;if(e.key==='Enter')deployAt(p);else{const step=e.shiftKey?5:20;if(e.key==='ArrowUp')p.y-=step;if(e.key==='ArrowDown')p.y+=step;if(e.key==='ArrowLeft')p.x-=step;if(e.key==='ArrowRight')p.x+=step;p.x=Math.max(28,Math.min(WIDTH-28,p.x));p.y=Math.max(40,Math.min(HEIGHT-28,p.y))}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(game.status==='wave')paused=true;save();updateHUD()}});window.addEventListener('beforeunload',save);
let frameLast=0,accumulator=0,hudTime=0,saveTime=0;
function frame(now){const elapsed=Math.min(.1,(now-frameLast)/1000||0);frameLast=now;if(!paused&&!modal){accumulator+=elapsed*speed;let steps=0;while(accumulator>=1/60&&steps<20){game.step(1/60);accumulator-=1/60;steps++}}else accumulator=0;
 const events=game.events.splice(0);renderer.push(events);for(const e of events){audioSystem.play(e.type);if(e.type==='clear'){updateProfile();toast(`Wave ${e.wave} cleared · +${num(e.bonus)} credits${e.income?' · includes '+e.income+' science income':''}`);save()}if(e.type==='wave')roundBanner('ROUND '+e.wave,e.wave%10===0?'BOSS ROUND':'DEFEND THE CITY');if(e.type==='boss'){roundBanner(e.name.toUpperCase(),'BOSS INCOMING');toast(e.name+' has entered the battlefield.');}if(e.type==='victory'){recordVictory();showResult()}if(e.type==='defeat'){updateProfile();save();showResult()}if(e.type==='ability')toast(e.name+' activated.');}
 if(events.length)updateProfile();renderer.draw(game,selected,placing,now,paused||!!modal,speed);hudTime+=elapsed;saveTime+=elapsed;if(hudTime>=.12){updateHUD();hudTime=0}if(saveTime>=5){save();saveTime=0}requestAnimationFrame(frame);
}
renderPanel();updateHUD();updateProfile();requestAnimationFrame(frame);if(restored){toast('Mission restored. Your team is waiting.');if(['victory','defeat'].includes(game.status))showResult()}
